head.script:
scwin.onpageload = function () {

};


/**
 * @method
 * @name initMainLoad
 * @description 화면 초기 로딩. 현재 비활성(no-op) — 사이드/헤더 프레임 초기화 코드는 비활성 처리되어 있던
 * 도달 불가 코드를 삭제했다(git 이력 참조). 메인 레이아웃 화면에서 재구현 시 사용한다.
 * @returns {void}
 * @hidden N
 * @exception
 * @example main.initMainLoad();
 */
scwin.initMainLoad = function () {
    return;
};

/**
 * @method
 * @name setHeaderMenu
 * @description header menu 생성 (헤더 프레임의 메뉴 css 적용을 호출한다)
 * @returns {void}
 * @hidden N
 * @exception
 * @example main.setHeaderMenu();
 */
scwin.setHeaderMenu = function () {
    //pfm_header.getWindow().scwin.setGenerator(); // 메뉴 생성
    pfm_header.getWindow().scwin.setMenuCss(); // 메뉴 css 적용
};

/**
 * @method
 * @name getLayoutId
 * @description 메인 레이아웃 아이디 정보를 반환한다.
 * @returns {String} 레이아웃 구분 (T:TabControl, M:WindowContainer, S:단일 프레임, 해당 없음 null)
 * @hidden N
 * @exception
 * @example const layout = main.getLayoutId();
 */
scwin.getLayoutId = function () {
    if (typeof $p.main().pfm_main.scope.$p.getComponentById("tac_layout") === "object") {
        return "T";
    } else if (typeof $p.main().pfm_main.scope.$p.getComponentById("wdc_main") === "object") {
        return "M";
    } else if (typeof $p.main().pfm_main.scope.$p.getComponentById("pfm_layout") === "object") {
        return "S";
    }
    return null;
};

/**
 * @method
 * @name isMobileSize
 * @description 화면 해상도가 모바일 사이즈(가로 1024px 이하)인지 반환한다.
 * @returns {Boolean} 모바일 사이즈 여부
 * @hidden N
 * @exception
 * @example if (main.isMobileSize()) { ... }
 */
scwin.isMobileSize = function () {
    const size = {
        width: window.innerWidth || document.body.clientWidth,
        height: window.innerHeight || document.body.clientHeight
    };

    return size.width <= 1024;
};

/**
 * @method
 * @name closeBeforePage
 * @description 화면이 닫히기 전에 변경된 데이터가 있는지 검사하고, 있으면 닫기 여부를 확인받는다.
 * @param {Object} frameObj 닫으려는 화면의 wframe obj
 * @returns {Boolean} 닫기 진행 여부
 * @hidden N
 * @exception
 * @example const isClose = main.closeBeforePage(frameObj);
 */
scwin.closeBeforePage = function (frameObj) {
    if (checkBeforeCloseModified(frameObj)) {
        // 호출부($c.win 닫기 흐름)가 반환값을 동기로 소비하므로 네이티브 confirm 을 유지한다
        // ($c.win.confirm 은 Promise 기반 비동기라 1:1 치환 불가)
        if (confirm($c.data.getMessage("MSG_CM_00006"))) {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }

    function checkBeforeCloseModified(frameObj) {
        const changeCheckMainFrame = $c.data.getChangeCheckedMainFrame(frameObj.scope.$p);
        if (!$c.util.isEmpty(changeCheckMainFrame)) {
            const changeCheckDcList = $c.data.getChangeCheckedMainFrame(frameObj.scope.$p)._changeCheckDcList;

            if (!$c.util.isEmpty(changeCheckDcList) && $c.util.isArray(changeCheckDcList) && (changeCheckDcList.length > 0)) {
                for (let i = 0; i < changeCheckDcList.length; i++) {
                    const dlObj = $c.util.getComponent(changeCheckDcList[i]);
                    if (!$c.util.isEmpty(dlObj) && (dlObj.getObjectType() == "dataList" || dlObj.getObjectType() == "dataMap")) {
                        if (dlObj.getModifiedIndex().length > 0) {
                            return true;
                        }
                    }
                }
            }
        }

        return false;
    };
};

/**
 * @method
 * @name pushStateMain
 * @description 메인 화면으로 History를 저장한다.
 * @returns {void}
 * @hidden N
 * @exception
 * @example main.pushStateMain();
 */
scwin.pushStateMain = function () {
    const data = {
        menuInfo: {
            menuNm: "메인",
            menuCode: "MAIN"
        }
    };
    $c.win.pushState(data);
};
